refentry.refsect1:
&reftitle.description;
public mixedIo\Poll\Watcher::getData
Returns the value that was associated with the watcher by Io\Poll\Context::add, Io\Poll\Watcher::modify or Io\Poll\Watcher::modifyData.

  &reftitle.examples;

   Dispatching to a callback stored as watcher data


<?php
use Io\Poll\Context;
use Io\Poll\Event;
use Time\Duration;

[$reader, $writer] = stream_socket_pair(STREAM_PF_UNIX, STREAM_SOCK_STREAM, STREAM_IPPROTO_IP);

$context = new Context();
$context->add(new StreamPollHandle($reader), [Event::Read], fn(string $data) => strtoupper($data));

fwrite($writer, 'ping');

foreach ($context->wait(Duration::fromSeconds(1)) as $watcher) {
    $callback = $watcher->getData();
    echo $callback(fread($reader, 1024)), PHP_EOL;
}


   &example.outputs;


PING
